import { selectContact, type ContactRecord } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(message);
}

const records: ContactRecord[] = [
  { key: "Alpha", displayName: "First", address: "", picture: null, active: false },
  { key: "Alpha", displayName: "Second", address: "two", picture: "pic", active: true },
  { key: "alpha", displayName: "Lower", address: "three", picture: "", active: true }
];
const originalOrder = records.slice();

for (const key of ["", " Alpha", "Alpha ", "\tAlpha", "Alpha\n", " "]) {
  equal(selectContact(records, key).kind, "invalid-key", `expected invalid key: ${JSON.stringify(key)}`);
}

equal(selectContact([], "missing").kind, "not-found", "empty collection should not find a contact");
equal(selectContact(records, "ALPHA").kind, "not-found", "matching must be case-sensitive");

const lower = selectContact(records, "alpha");
assert(lower.kind === "found", "exact lowercase key should be found");
if (lower.kind === "found") {
  equal(lower.contact.displayName, "Lower", "all fields should be preserved");
  equal(lower.contact.picture, "", "empty picture should be preserved");
}

const found = selectContact(records, "Alpha");
assert(found.kind === "found", "matching key should be found");
if (found.kind === "found") {
  equal(found.contact.displayName, "First", "first matching record should win");
  equal(found.contact.address, "", "empty address should be preserved");
  equal(found.contact.picture, null, "null picture should be preserved");
  equal(found.contact.active, false, "false active value should be preserved");
  assert(found.contact !== records[0], "found contact must be newly allocated");
  found.contact.displayName = "changed";
  found.contact.active = true;
}

equal(records[0].displayName, "First", "mutating result must not mutate input");
equal(records[0].active, false, "mutating result must not mutate input fields");
assert(records[0] === originalOrder[0] && records[1] === originalOrder[1] && records[2] === originalOrder[2], "input order must remain unchanged");

